UPDATE warning_record
SET ai_summary = #{aiSummary}, measure = #{measure}, ref_cases = #{refCases}
WHERE id = #{id}

UPDATE warning_record
SET ai_summary = #{aiSummary}, measure = #{measure}
WHERE id = #{id}

UPDATE warning_record
SET respond_status = 'RESPONDED', respond_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT w.id, w.warning_no, w.rule_id, w.warning_level, w.category, w.sub_category, w.region,
       w.county_name, w.department, w.trigger_time, w.status, w.review_time, w.related_attention,
       w.ai_summary, w.measure, w.ref_cases, w.respond_status, w.respond_time,
       r.rule_name AS rule_name
FROM warning_record w
LEFT JOIN warning_rule r ON w.rule_id = r.id

    AND w.warning_level = #{warningLevel}
    AND w.category = #{category}
    AND w.region = #{region}
    AND w.status = #{status}
    AND w.trigger_time >= #{startTime}
    AND w.trigger_time <= #{endTime}

ORDER BY CASE WHEN w.status = 'PENDING' AND w.warning_level = 'URGENT' THEN 0 ELSE 1 END,
         w.trigger_time DESC, w.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM warning_record

    AND warning_level = #{warningLevel}
    AND category = #{category}
    AND region = #{region}
    AND status = #{status}
    AND trigger_time >= #{startTime}
    AND trigger_time <= #{endTime}

SELECT w.id, w.warning_no, w.rule_id, w.warning_level, w.category, w.sub_category, w.region,
       w.county_name, w.department, w.trigger_time, w.status, w.review_time, w.related_attention,
       w.ai_summary, w.measure, w.ref_cases, w.respond_status, w.respond_time,
       r.rule_name AS rule_name
FROM warning_record w
LEFT JOIN warning_rule r ON w.rule_id = r.id
WHERE w.status = 'SENT'

    AND (FIND_IN_SET(#{dept}, w.department) > 0
         OR FIND_IN_SET(CONCAT(#{countyCode}, ':', #{dept}), w.department) > 0)

AND w.sub_category = #{subCategory}
AND w.warning_level = #{warningLevel}
AND w.region = #{region}
AND w.trigger_time >= #{startTime}
AND w.trigger_time <= #{endTime}
ORDER BY w.trigger_time DESC, w.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM warning_record w
WHERE w.status = 'SENT'

    AND (FIND_IN_SET(#{dept}, w.department) > 0
         OR FIND_IN_SET(CONCAT(#{countyCode}, ':', #{dept}), w.department) > 0)

AND w.sub_category = #{subCategory}
AND w.warning_level = #{warningLevel}
AND w.region = #{region}
AND w.trigger_time >= #{startTime}
AND w.trigger_time <= #{endTime}

SELECT w.id, w.warning_no, w.rule_id, w.warning_level, w.category, w.sub_category, w.region,
       w.county_name, w.department, w.trigger_time, w.status, w.review_time, w.related_attention,
       w.ai_summary, w.measure, w.ref_cases,
       d.respond_status AS respond_status, d.respond_time AS respond_time,
       d.dispatch_time AS dispatch_time,
       r.rule_name AS rule_name
FROM warning_street_dispatch d
JOIN warning_record w ON w.id = d.warning_id
LEFT JOIN warning_rule r ON w.rule_id = r.id
WHERE w.status = 'SENT'
  AND d.street_office = #{streetOffice}
AND w.sub_category = #{subCategory}
AND w.warning_level = #{warningLevel}
AND (w.region = #{region} OR w.county_name = #{region})
AND w.trigger_time >= #{startTime}
AND w.trigger_time <= #{endTime}
ORDER BY w.trigger_time DESC, w.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM warning_street_dispatch d
JOIN warning_record w ON w.id = d.warning_id
WHERE w.status = 'SENT'
  AND d.street_office = #{streetOffice}
AND w.sub_category = #{subCategory}
AND w.warning_level = #{warningLevel}
AND (w.region = #{region} OR w.county_name = #{region})
AND w.trigger_time >= #{startTime}
AND w.trigger_time <= #{endTime}

SELECT COUNT(1)
FROM warning_record
WHERE rule_id = #{ruleId} AND trigger_time >= #{dayStart}
